sources.app.tsx:
// Pixel toys: effects that compute every cell of the frame in JS and hand the
// cells to frameos.pixels, one palette byte each, written straight into the
// panel (no canvas, no SVG, no markup). Each effect is a module: fireworks
// and a fountain (particles with trails), a starfield, blobs (metaballs), a
// plasma and Life. The grid is the frame over pixelSize; each effect picks
// its own when asked for 0, coarser on an ESP32, where its JS runs slower.
import { setSeed } from './random'
import { counterIn, counterOut, counterReset } from './counter'
import { fireworks } from './fireworks'
import { fountain } from './fountain'
import { starfield } from './starfield'
import { blobs } from './blobs'
import { plasma } from './plasma'
import { life } from './life'

const EFFECTS: Record<string, any> = { fireworks, fountain, starfield, blobs, plasma, life }

// What outlives a render while the interpreter does. An ESP32 short of
// memory drops the interpreter, and the effect starts again.
let effect: any = null
let name = ''
let cols = 0
let rows = 0
let cells: any = null
let embedded: boolean | null = null

export function get(app, context) {
  counterOut() // the frame before this one has been written
  const config = app.config
  const which = EFFECTS[config.effect] ? config.effect : 'fireworks'
  const chosen = EFFECTS[which]
  if (embedded === null) embedded = app.frame.embedded === true
  const asked = Math.round(Number(config.pixelSize) || 0)
  const pixelSize = asked >= 1 ? Math.min(32, asked) : embedded ? chosen.embeddedSize : chosen.hostSize
  const width = Math.max(pixelSize, context.imageWidth || app.frame.width)
  const height = Math.max(pixelSize, context.imageHeight || app.frame.height)
  const w = Math.floor(width / pixelSize)
  const h = Math.floor(height / pixelSize)
  if (which !== name || w !== cols || h !== rows) {
    name = which
    effect = chosen
    cols = w
    rows = h
    const given = Math.round(Number(config.seed) || 0)
    setSeed(given > 0 ? given : Date.now() ^ (Math.random() * 0x7fffffff))
    cells = effect.init(w, h)
  }
  effect.step(cells)
  const askedFps = config.showFps
  if (askedFps === true || askedFps === 'true') {
    counterIn(cells, cols, rows, effect.textColor, effect.boxColor ?? 0, Math.ceil(4 / pixelSize))
  } else {
    counterReset()
  }
  return frameos.pixels(cells, { width: cols, height: rows, pixelSize, palette: effect.palette })
}

