// Palettes as 0xRRGGBB numbers, built once when an effect starts.

export function rgb(r: number, g: number, b: number): number {
  const c = (v: number) => Math.max(0, Math.min(255, Math.round(v)))
  return (c(r) << 16) | (c(g) << 8) | c(b)
}

/** A hue (0..1), saturation and value (0..1) as 0xRRGGBB. */
export function hsv(h: number, s: number, v: number): number {
  const i = Math.floor(h * 6)
  const f = h * 6 - i
  const p = v * (1 - s)
  const q = v * (1 - f * s)
  const t = v * (1 - (1 - f) * s)
  const k = ((i % 6) + 6) % 6
  const [r, g, b] = [[v, t, p], [q, v, p], [p, v, t], [p, q, v], [t, p, v], [v, p, q]][k]
  return rgb(r * 255, g * 255, b * 255)
}

/** Stops [at (0..1), 0xRRGGBB] blended into `count` colors. */
export function gradient(count: number, stops: [number, number][]): number[] {
  const out: number[] = []
  for (let i = 0; i < count; i++) {
    const at = count === 1 ? 0 : i / (count - 1)
    let k = 0
    while (k < stops.length - 2 && at > stops[k + 1][0]) k++
    const [a0, c0] = stops[k]
    const [a1, c1] = stops[k + 1]
    const f = a1 === a0 ? 0 : Math.max(0, Math.min(1, (at - a0) / (a1 - a0)))
    const mix = (shift: number) => ((c0 >> shift) & 255) * (1 - f) + ((c1 >> shift) & 255) * f
    out.push(rgb(mix(16), mix(8), mix(0)))
  }
  return out
}

sources.counter.ts:
// The FPS counter: the renders a second the panel really gets (simulation,
// blit and pacing included), in a 3x5 font written into the cells for the
// blit and taken out again before the next step, so it neither slows what it
// measures nor feeds the effect.
const GLYPHS: Record<string, number> = {
  0: 0x7b6f, 1: 0x2c97, 2: 0x73e7, 3: 0x73cf, 4: 0x5bc9, 5: 0x79cf, 6: 0x79ef, 7: 0x7249, 8: 0x7bef, 9: 0x7bcf,
  '-': 0x01c0, F: 0x79e4, P: 0x7be4, S: 0x79cf,
}

let fps: number | null = null
let frames = 0
let windowStart = 0
let label: Uint8Array | null = null
let under: Uint8Array | null = null
let key = ''
let width = 0
let height = 0
let scale = 1
let held: { cells: ArrayLike<number> & { set: any; subarray: any }; cols: number } | null = null

function count(): number | null {
  const now = Date.now()
  if (!windowStart) windowStart = now
  frames++
  const elapsed = now - windowStart
  if (elapsed >= 1000) {
    fps = Math.round((frames * 1000) / elapsed)
    frames = 0
    windowStart = now
  }
  return fps
}

/** Puts back what the label covered: before the effect's next step. */
export function counterOut() {
  if (!held || !under) return
  const { cells, cols } = held
  for (let y = 0; y < height; y++) cells.set(under.subarray(y * width, (y + 1) * width), (y + scale) * cols + scale)
  held = null
}

/** Forgets the count while the counter is off. */
export function counterReset() {
  frames = 0
  windowStart = 0
}

/** The label into the top-left corner of the cells, `text` and `box` palette indices. */
export function counterIn(cells: any, cols: number, rows: number, text: number, box: number, size: number) {
  const rate = count()
  const value = (rate === null ? '--' : rate) + ' FPS'
  const k = value + ':' + size + ':' + text + ':' + box
  if (k !== key) {
    key = k
    scale = size
    width = (value.length * 4 + 1) * size
    height = 7 * size
    label = new Uint8Array(width * height).fill(box)
    under = new Uint8Array(width * height)
    for (let g = 0; g < value.length; g++) {
      const bits = GLYPHS[value[g]] || 0
      for (let i = 0; i < 15; i++) {
        if (!(bits & (1 << (14 - i)))) continue
        const left = (g * 4 + 1 + (i % 3)) * size
        const top = (1 + Math.floor(i / 3)) * size
        for (let y = 0; y < size; y++) label.fill(text, (top + y) * width + left, (top + y) * width + left + size)
      }
    }
  }
  if (width + scale > cols || height + scale > rows || !label || !under) return
  for (let y = 0; y < height; y++) {
    const at = (y + scale) * cols + scale
    under.set(cells.subarray(at, at + width), y * width)
    cells.set(label.subarray(y * width, (y + 1) * width), at)
  }
  held = { cells, cols }
}

sources.trails.ts:
// Glowing dots that fade: a palette of 8 hues x 32 levels (index = hue * 32 +
// level, level 0 black), and a pass that dims every lit cell one step a frame
// through a table. The pass skips every row nothing was drawn in for 32
// frames, so the black sky costs nothing.
import { hsv } from './colors'

export const LEVELS = 32
export const HUES = 8

export function trailPalette(): number[] {
  const out: number[] = []
  for (let hue = 0; hue < HUES; hue++) {
    for (let level = 0; level < LEVELS; level++) {
      const v = Math.pow(level / (LEVELS - 1), 1.6)
      // The brightest levels whiten, as a spark's core does.
      const s = level > LEVELS - 6 ? 0.85 - (level - (LEVELS - 6)) * 0.15 : 0.85
      out.push(level === 0 ? 0 : hsv(hue / HUES, s, v))
    }
  }
  return out
}

export class Trails {
  cols: number
  rows: number
  fade: Uint8Array
  live: Uint8Array

  constructor(cols: number, rows: number, step: number) {
    this.cols = cols
    this.rows = rows
    this.fade = new Uint8Array(256)
    for (let i = 0; i < 256; i++) {
      const level = i & (LEVELS - 1)
      this.fade[i] = level > step ? i - step : 0
    }
    this.live = new Uint8Array(rows)
  }

  /** A dot at cell (x, y), `hue` 0..7, `level` 1..31; nothing off the grid. */
  plot(cells: Uint8ClampedArray, x: number, y: number, hue: number, level: number) {
    x |= 0
    y |= 0
    if (x < 0 || y < 0 || x >= this.cols || y >= this.rows) return
    const at = y * this.cols + x
    const value = hue * LEVELS + level
    if ((cells[at] & (LEVELS - 1)) < level) cells[at] = value
    this.live[y] = LEVELS
  }

  /** Every lit cell one step darker; rows with nothing lit are not read. */
  dim(cells: Uint8ClampedArray) {
    const F = this.fade
    const live = this.live
    const w = this.cols
    for (let y = 0; y < this.rows; y++) {
      if (live[y] === 0) continue
      live[y]--
      for (let i = y * w, end = i + w; i < end; i++) cells[i] = F[cells[i]]
    }
  }
}

sources.fireworks.ts:
// Fireworks: rockets climb from the bottom, burst at the top of their arc
// into a ring of sparks of one hue, and the sparks fall and fade, leaving
// trails. Everything is in cell units, so the show fits any grid.
import { between, random } from './random'
import { Particles } from './particles'
import { LEVELS, HUES, Trails, trailPalette } from './trails'

const ROCKET = 1
const SPARK = 0

let parts: Particles
let trails: Trails
let cols = 0
let rows = 0
let frame = 0

function launch() {
  const x = between(cols * 0.15, cols * 0.85)
  // High enough to burst in the top third: v^2 = 2 g h.
  const climb = between(rows * 0.45, rows * 0.8)
  const g = rows * 0.0016
  parts.add(x, rows - 1, between(-0.15, 0.15) * cols * 0.01, -Math.sqrt(2 * g * climb), 1, (random() * HUES) | 0, ROCKET)
}

function burst(x: number, y: number, hue: number) {
  const n = 30 + ((random() * 40) | 0)
  const speed = rows * between(0.012, 0.02)
  for (let k = 0; k < n; k++) {
    const a = (k / n) * Math.PI * 2 + random() * 0.2
    const v = speed * between(0.6, 1)
    parts.add(x, y, Math.cos(a) * v, Math.sin(a) * v, between(35, 60), random() < 0.15 ? (hue + 1) % HUES : hue)
  }
}

export const fireworks = {
  palette: trailPalette(),
  textColor: 7 * LEVELS + LEVELS - 1,
  embeddedSize: 4,
  hostSize: 2,

  init(w: number, h: number): Uint8ClampedArray {
    cols = w
    rows = h
    frame = 0
    parts = new Particles(900)
    trails = new Trails(w, h, 1)
    for (let i = 0; i < 3; i++) launch()
    return new Uint8ClampedArray(w * h)
  },

  step(cells: Uint8ClampedArray) {
    trails.dim(cells)
    frame++
    if (random() < 0.045 || parts.count === 0) launch()
    const g = rows * 0.0016
    const P = parts
    for (let i = P.count - 1; i >= 0; i--) {
      let vy = P.vy[i] + g
      const x = P.x[i] + P.vx[i]
      const y = P.y[i] + vy
      if (P.kind[i] === ROCKET) {
        if (vy >= 0) {
          burst(x, y, P.hue[i])
          P.remove(i)
          continue
        }
        trails.plot(cells, x, y, 1, 18 + ((random() * 10) | 0))
      } else {
        P.vx[i] *= 0.985
        vy *= 0.985
        const life = P.life[i] - 1
        if (life <= 0 || y >= rows) {
          P.remove(i)
          continue
        }
        P.life[i] = life
        // Bright while young, then dimmer; a spark twinkles as it dies.
        const level = life > 20 ? LEVELS - 1 : life < 8 && random() < 0.4 ? 4 : 10 + life
        trails.plot(cells, x, y, P.hue[i], level)
      }
      P.x[i] = x
      P.y[i] = y
      P.vy[i] = vy
    }
  },
}

sources.fountain.ts:
// A fountain: droplets thrown up from the bottom, falling back and bouncing
// off the floor, the color drifting through the rainbow as the stream plays.
import { between, random } from './random'
import { Particles } from './particles'
import { LEVELS, HUES, Trails, trailPalette } from './trails'

let parts: Particles
let trails: Trails
let cols = 0
let rows = 0
let frame = 0

export const fountain = {
  palette: trailPalette(),
  textColor: 7 * LEVELS + LEVELS - 1,
  embeddedSize: 4,
  hostSize: 2,

  init(w: number, h: number): Uint8ClampedArray {
    cols = w
    rows = h
    frame = 0
    parts = new Particles(700)
    trails = new Trails(w, h, 3)
    return new Uint8ClampedArray(w * h)
  },

  step(cells: Uint8ClampedArray) {
    trails.dim(cells)
    frame++
    const g = rows * 0.0012
    // The jet sways, and its color walks the hues.
    const sway = Math.sin(frame * 0.02) * 0.35
    const hue = ((frame / 90) | 0) % HUES
    const up = Math.sqrt(2 * g * rows * 0.75)
    for (let k = 0; k < 6; k++) {
      parts.add(cols / 2 + between(-0.5, 0.5), rows - 1, (sway + between(-0.25, 0.25)) * up * 0.35,
        -up * between(0.85, 1), between(150, 260), random() < 0.1 ? (hue + 1) % HUES : hue)
    }
    const P = parts
    const floor = rows - 1
    for (let i = P.count - 1; i >= 0; i--) {
      let vx = P.vx[i]
      let vy = P.vy[i] + g
      let x = P.x[i] + vx
      let y = P.y[i] + vy
      const life = P.life[i] - 1
      if (life <= 0 || x < 0 || x >= cols) {
        P.remove(i)
        continue
      }
      if (y >= floor) {
        // A bounce loses most of the fall; a slow drop settles and goes.
        y = floor
        vy = -vy * 0.45
        vx *= 0.8
        if (vy > -g * 4) {
          P.remove(i)
          continue
        }
      }
      P.x[i] = x
      P.y[i] = y
      P.vx[i] = vx
      P.vy[i] = vy
      P.life[i] = life
      trails.plot(cells, x, y, P.hue[i], vy < 0 ? LEVELS - 1 : LEVELS - 4)
    }
  },
}

sources.starfield.ts:
// A starfield: stars come at you out of the middle of the panel, brighter
// and longer as they near, each drawn as a streak from where it was. What a
// frame drew is remembered and cleared before the next.
import { between, random } from './random'
import { gradient } from './colors'

const N = 170
let x: Float32Array
let y: Float32Array
let z: Float32Array
let drawn: Int32Array
let drawnCount = 0
let cols = 0
let rows = 0

function respawn(i: number, far: boolean) {
  x[i] = between(-1, 1)
  y[i] = between(-1, 1)
  z[i] = far ? between(0.85, 1) : between(0.1, 1)
}

export const starfield = {
  palette: gradient(32, [[0, 0x000000], [0.35, 0x202c55], [0.75, 0xb8c8ff], [1, 0xffffff]]),
  textColor: 31,
  embeddedSize: 4,
  hostSize: 2,

  init(w: number, h: number): Uint8ClampedArray {
    cols = w
    rows = h
    x = new Float32Array(N)
    y = new Float32Array(N)
    z = new Float32Array(N)
    drawn = new Int32Array(N * 12)
    drawnCount = 0
    for (let i = 0; i < N; i++) respawn(i, false)
    return new Uint8ClampedArray(w * h)
  },

  step(cells: Uint8ClampedArray) {
    for (let k = 0; k < drawnCount; k++) cells[drawn[k]] = 0
    drawnCount = 0
    const cx = cols / 2
    const cy = rows / 2
    const scale = Math.min(cols, rows) * 0.5
    for (let i = 0; i < N; i++) {
      const z0 = z[i]
      const z1 = z0 - 0.012
      if (z1 <= 0.02) {
        respawn(i, true)
        continue
      }
      z[i] = z1
      const x0 = cx + (x[i] / z0) * scale
      const y0 = cy + (y[i] / z0) * scale
      const x1 = cx + (x[i] / z1) * scale
      const y1 = cy + (y[i] / z1) * scale
      if (x1 < 0 || y1 < 0 || x1 >= cols || y1 >= rows) {
        respawn(i, true)
        continue
      }
      const level = Math.min(31, ((1 - z1) * 34) | 0)
      const steps = Math.min(10, Math.max(1, Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0)) | 0))
      for (let s = 0; s <= steps; s++) {
        const f = s / steps
        const px = (x0 + (x1 - x0) * f) | 0
        const py = (y0 + (y1 - y0) * f) | 0
        if (px < 0 || py < 0 || px >= cols || py >= rows) continue
        const at = py * cols + px
        // The head brightest, the tail fading behind it.
        const v = (level * (0.35 + 0.65 * f)) | 0
        if (cells[at] < v) cells[at] = v
        drawn[drawnCount++] = at
      }
    }
  },
}

sources.blobs.ts:
// Blobs: a lava lamp of metaballs. Each blob adds its falloff to the cells
// within its radius (a table by squared distance, so no root or division per
// cell), the cells clamp at 255, and the palette draws the surface where the
// sum crosses the middle: a glow outside, a bright rim, a hot core inside.
import { between } from './random'
import { gradient } from './colors'

const K = 6
let cols = 0
let rows = 0
let frame = 0
let radius = 0
let r2 = 0
let fall: Uint8Array
const fx = new Float32Array(K)
const fy = new Float32Array(K)
const px = new Float32Array(K)
const py = new Float32Array(K)

export const blobs = {
  palette: gradient(256, [
    [0, 0x05020f], [0.3, 0x1c0838], [0.46, 0x5a1580], [0.5, 0xffd2ef], [0.53, 0xff3c8c],
    [0.75, 0xff7a2a], [1, 0xffe27a],
  ]),
  textColor: 255,
  embeddedSize: 8,
  hostSize: 4,

  init(w: number, h: number): Uint8ClampedArray {
    cols = w
    rows = h
    frame = 0
    radius = Math.max(3, Math.min(w, h) * 0.2)
    r2 = Math.ceil(radius * radius)
    fall = new Uint8Array(r2 + 2) // two zeros past the edge, for rounding
    for (let d = 0; d < r2; d++) {
      const t = 1 - d / r2
      fall[d] = Math.min(255, Math.round(512 * t * t))
    }
    for (let k = 0; k < K; k++) {
      fx[k] = between(0.006, 0.016)
      fy[k] = between(0.006, 0.016)
      px[k] = between(0, Math.PI * 2)
      py[k] = between(0, Math.PI * 2)
    }
    return new Uint8ClampedArray(w * h)
  },

  step(cells: Uint8ClampedArray) {
    frame++
    cells.fill(0)
    const F = fall
    const w = cols
    for (let k = 0; k < K; k++) {
      const bx = w * (0.5 + 0.36 * Math.sin(frame * fx[k] + px[k]))
      const by = rows * (0.5 + 0.36 * Math.sin(frame * fy[k] + py[k]))
      const y0 = Math.max(0, Math.ceil(by - radius))
      const y1 = Math.min(rows - 1, Math.floor(by + radius))
      for (let y = y0; y <= y1; y++) {
        const dy = y - by
        const dy2 = dy * dy
        const span = Math.sqrt(Math.max(0, r2 - dy2))
        const x0 = Math.max(0, Math.ceil(bx - span))
        const x1 = Math.min(w - 1, Math.floor(bx + span))
        let j = y * w + x0
        for (let x = x0; x <= x1; x++, j++) {
          const dx = x - bx
          cells[j] += F[(dy2 + dx * dx) | 0]
        }
      }
    }
  },
}

sources.plasma.ts:
// Plasma: three waves summed per cell, from tables made once a frame (a row's
// part, a column's, a diagonal's), so a cell is two reads and two adds. The
// cells are a Uint8Array, so the sum wraps round the palette by itself.
import { random } from './random'

let cols = 0
let rows = 0
let frame = 0
let a: Uint8Array
let b: Uint8Array
let c: Uint8Array
const SIN = new Uint8Array(256)
for (let i = 0; i < 256; i++) SIN[i] = Math.round(127.5 + 127.5 * Math.sin((i / 256) * Math.PI * 2))
let k1 = 0
let k2 = 0
let k3 = 0

function cosinePalette(): number[] {
  const out: number[] = []
  for (let i = 0; i < 256; i++) {
    const t = i / 256
    const ch = (d: number) => Math.round(255 * (0.5 + 0.5 * Math.cos(Math.PI * 2 * (t + d))))
    out.push((ch(0) << 16) | (ch(0.33) << 8) | ch(0.67))
  }
  return out
}

const PALETTE = cosinePalette()
const luma = (c: number) => ((c >> 16) & 255) * 77 + ((c >> 8) & 255) * 150 + (c & 255) * 29
const brightest = PALETTE.reduce((best, c, i) => (luma(c) > luma(PALETTE[best]) ? i : best), 0)
const darkest = PALETTE.reduce((best, c, i) => (luma(c) < luma(PALETTE[best]) ? i : best), 0)

export const plasma = {
  palette: PALETTE,
  textColor: brightest,
  boxColor: darkest,
  embeddedSize: 8,
  hostSize: 4,

  init(w: number, h: number): Uint8Array {
    cols = w
    rows = h
    frame = 0
    a = new Uint8Array(w)
    b = new Uint8Array(h)
    c = new Uint8Array(w + h)
    // The waves' lengths follow the grid, so the picture is the same at any
    // cell size; the seed picks their mix.
    k1 = 256 / w * (1 + random())
    k2 = 256 / h * (1 + random())
    k3 = 128 / (w + h) * (1 + random() * 2)
    return new Uint8Array(w * h)
  },

  step(cells: Uint8Array) {
    frame++
    const t = frame
    for (let x = 0; x < cols; x++) a[x] = (SIN[(x * k1 + t * 2) & 255] + SIN[(x * k1 * 0.5 - t) & 255]) >> 2
    for (let y = 0; y < rows; y++) b[y] = (SIN[(y * k2 - t * 3) & 255] + SIN[(y * k2 * 0.7 + t * 2) & 255]) >> 2
    for (let d = 0; d < cols + rows; d++) c[d] = SIN[(d * k3 + t * 4) & 255] >> 1
    const A = a
    const C = c
    const w = cols
    let j = 0
    for (let y = 0; y < rows; y++) {
      const by = b[y] + t
      for (let x = 0; x < w; x++) cells[j++] = A[x] + by + C[x + y]
    }
  },
}
